public enum GitRuntimeConfigurationState { Unconfigured, Invalid, Configured }
public sealed class GitRuntimeOptions
{
 public const string SectionName="Platform:SoftwareFactory:GitRuntime";public string Endpoint{get;init;}=string.Empty;public string GatewayProfile{get;init;}=string.Empty;public string OperatorId{get;init;}=string.Empty;public string SignatureAlgorithm{get;init;}=string.Empty;public Dictionary<string,string> TrustedPublicKeysPem{get;init;}=new(StringComparer.Ordinal);public int RequestTimeoutSeconds{get;init;}public int MaximumRequestBytes{get;init;}public int MaximumResponseBytes{get;init;}
 public GitRuntimeConfigurationState ConfigurationState{get{if(new[]{Endpoint,GatewayProfile,OperatorId,SignatureAlgorithm}.All(string.IsNullOrWhiteSpace)&&TrustedPublicKeysPem.Count==0&&RequestTimeoutSeconds==0&&MaximumRequestBytes==0&&MaximumResponseBytes==0)return GitRuntimeConfigurationState.Unconfigured;if(!Uri.TryCreate(Endpoint,UriKind.Absolute,out var u)||u.Scheme!=Uri.UriSchemeHttps||!string.IsNullOrEmpty(u.UserInfo)||!string.IsNullOrEmpty(u.Query)||!string.IsNullOrEmpty(u.Fragment)||string.IsNullOrWhiteSpace(GatewayProfile)||string.IsNullOrWhiteSpace(OperatorId)||SignatureAlgorithm is not("RS256" or "ES256")||TrustedPublicKeysPem.Count==0||TrustedPublicKeysPem.Any(x=>string.IsNullOrWhiteSpace(x.Key)||!x.Value.Contains("PUBLIC KEY",StringComparison.Ordinal))||RequestTimeoutSeconds<=0||MaximumRequestBytes<=0||MaximumResponseBytes<=0)return GitRuntimeConfigurationState.Invalid;return GitRuntimeConfigurationState.Configured;}}public bool IsOperationallyConfigured=>ConfigurationState==GitRuntimeConfigurationState.Configured;
}
public sealed record GitRuntimeReadiness(GitRuntimeConfigurationState State);

public sealed class SovereignGitPolicyGate(IPolicyBundleVerifier bundleVerifier,ISovereignPolicyEvaluationClient client):IGitPolicyGate
{
