ssException("Git action scope missing.");if(e.HumanReview is not null||e.Tests is not null||e.Sandbox is not null||e.SecurityValidation is not null||e.StaticValidation is not null||e.CodeGeneration is not null||e.AiPlanning is not null||e.ApprovedPackages is not null||e.ExistingArchitecture is not null||e.ExistingSystems is not null||!e.AllowedResourceIds.IsDefaultOrEmpty||!e.AllowedModalities.IsDefaultOrEmpty||!e.RequiredRoles.IsDefaultOrEmpty||e.MaximumResults!=0)throw new UnauthorizedAccessException("Git decision mixed scopes.");if(!Enum.TryParse<DataClassification>(s.MaximumClassification,true,out var c)||!s.AllowedRelativePaths.ToImmutableHashSet(StringComparer.Ordinal).SetEquals(i.AuthorizedRelativePaths)||s.RepositoryId!=i.RepositoryId||!StringComparer.OrdinalIgnoreCase.Equals(s.ExpectedBaseCommitId,i.ExpectedBaseCommitId)||s.ChangeBranch!=i.ChangeBranch||s.CommitMessage!=i.CommitMessage||s.SigningPolicyReference!=i.SigningPolicyReference||s.ProtectedBranch||s.ForceUpdateAllowed||s.CiCdTriggerAllowed||s.RequiredRoles.IsDefaultOrEmpty||s.OutputKind!="git-commit-result")throw new UnauthorizedAccessException("Git scope mismatch.");return Make(i,v,d,GovernedIntentPolicyOutcome.Permit,c,s.AllowedRelativePaths.ToImmutableHashSet(StringComparer.Ordinal),s.ProtectedBranch,s.ForceUpdateAllowed,s.CiCdTriggerAllowed,s.RequiredRoles.ToImmutableHashSet(StringComparer.Ordinal),s.OutputKind);}
 private static GitPolicyDecision Make(GitPolicyInput i,PolicyBundleVerification v,SovereignPolicyEvaluationDecision d,GovernedIntentPolicyOutcome o,DataClassification c,ImmutableHashSet<string> paths,bool protectedBranch,bool force,bool ci,ImmutableHashSet<string> roles,string output)=>new(i.DecisionRequestId,i.OperationId,i.ReviewId,i.TestsExecutionId,i.GenerationId,i.DeliveryRunId,i.TenantId,i.Environment,i.CandidateSha256Digest,i.ReviewPackageSha256Digest,i.TestsResultSha256Digest,i.ChangeSetSha256Digest,paths,i.RepositoryId,i.ExpectedBaseCommitId,i.ChangeBranch,i.CommitMessage,i.SigningPolicyReference,protectedBranch,force,ci,v.BundleId,v.Version,v.Sha256Digest,true,v.VerificationEvidenceReference,o,c,roles,output,d.Reasons,d.EvidenceReferences,d.DecidedAt);
}

public sealed class SovereignHttpInstitutionalGitGateway(IHttpClientFactory factory,IOptions<GitRuntimeOptions> configured):IGovernedGitChangeSetMaterializer,IGitChangePolicyValidator,IInstitutionalGitGateway
{
 private static readonly JsonSerializerOptions Json=new(JsonSerializerDefaults.Web);
 public Task<GovernedGitChangeSet> MaterializeAsync(Guid operationId,AiCandidateArtifact candidate,ImmutableHashSet<string> paths,CancellationToken ct)=>Invoke<GovernedGitChangeSet>("materialize",new{operationId,candidate,authorizedRelativePaths=paths.Order(StringComparer.Ordinal)},ct);
 public Task<GitChangePolicyDecision> ValidateAsync(GitChangePolicyRequest request,CancellationToken ct)=>Invoke<GitChangePolicyDecision>("validate",request,ct);
 public Task<InstitutionalGitCommitResult> CommitAsync(InstitutionalGitCommitRequest request,CancellationToken ct)=>Invoke<InstitutionalGitCommitResult>("commit",request,ct);
 private async Task<T> Invoke<T>(string action,object request,CancellationToken ct){var o=configured.Value;if(!o.IsOperationallyConfigured)throw new GitDependencyUnavailableException("Institutional Git gateway is not configured.");var id=Guid.NewGuid();var requestJson=JsonSerializer.Serialize(request,Json);var input=Hash($"{id:D}|{action}|{o.OperatorId}|{o.GatewayProfile}|{Hash(requestJson)}");var bytes=JsonSerializer.SerializeToUtf8Bytes(new GatewayRequest(id,action,o.OperatorId,o.GatewayProfile,input,request),Json);if(bytes.Length>o.MaximumRequestBytes)throw new UnauthorizedAccessException("Git gateway request exceeds bound.");using var msg=new HttpRequestMessage(HttpMethod.Post,o.Endpoint){Content=new ByteArrayContent(bytes)};msg.Headers.Add("X-Governed-Operation",action);msg.Content.Headers.ContentType=new("application/json");using var timeout=CancellationTokenSource.CreateLinkedTokenSource(ct);timeout.CancelAfter(TimeSpan.FromSeconds(o.RequestTimeoutSeconds));try{using var response=await factory.CreateClient("sovereign-institutional-git").SendAsync(msg,HttpCompletionOption.ResponseHeadersRead,timeout.Token);if(!response.IsSuccessStatusCode)throw new GitDependencyUnavailableException("Institutional Git gateway rejected request.");var body=await SovereignAiHttp.ReadBoundedAsync(response.Content,o.MaximumResponseBytes,timeout.Token);var r=JsonSerializer.Deserialize<GatewayResponse<T>>(body,Json)??throw new InvalidOperationException("Empty Git gateway response.");if(r.InvocationId!=id||r.Action!=action||r.OperatorId!=o.OperatorId||r.GatewayProfile!=o.GatewayProfile||!StringComparer.OrdinalIgnoreCase.Equals(r.InputSha256Digest,input)||r.Payload is null||string.IsNullOrWhiteSpace(r.EvidenceReference)||r.CompletedAt==default||r.Signature.SignedAt<r.CompletedAt)throw new UnauthorizedAccessException("Git gateway response binding invalid.");var payloadHash=Hash(JsonSerializer.Serialize(r.Payload,Json));var signed=$"{r.InvocationId:D}|{r.Action}|{r.OperatorId}|{r.GatewayProfile}|{r.InputSha256Digest}|{payloadHash}|{r.EvidenceReference}|{r.CompletedAt:O}|{r.Signature.Algorithm}|{r.Signature.KeyId}|{r.Signature.CertificateChainReference}|{r.Signature.SignedAt:O}";if(!AiPlanningSignatureVerifier.Verify(o.SignatureAlgorithm,o.TrustedPublicKeysPem,r.Signature,SHA256.HashData(Encoding.UTF8.GetBytes(signed))))throw new UnauthorizedAccessException("Git gateway signature invalid.");return r.Payload;}catch(OperationCanceledException)when(!ct.IsCancellationRequested){throw new GitDependencyUnavailableException("Institutional Git gateway timed out.");}catch(HttpRequestException){throw new GitDependencyUnavailableException("Institutional Git gateway unavailable.");}}
 private static string Hash(string value)=>Convert.ToHexStringLower(SHA256.HashData(Encoding.UTF8.GetBytes(value)));private sealed record GatewayRequest(Guid InvocationId,string Action,string OperatorId,string GatewayProfile,string InputSha256Digest,object Payload);private sealed record GatewayResponse<T>(Guid InvocationId,string Action,string OperatorId,string GatewayProfile,string InputSha256Digest,T Payload,string EvidenceReference,DateTimeOffset CompletedAt,SignatureEnvelope Signature);
}

public sealed class DeterministicGitResultAuthorizer(IAccessPolicyEvaluator access):IGitResultAuthorizer
{
 public Task<GitResultAuthorizationDecision> AuthorizeAsync(GitResultAuthorizationRequest r,CancellationToken ct){ct.ThrowIfCancellationRequested();if(!r.Identity.IsAuthenticated||r.Identity.SubjectId!=r.SubjectId||r.RequiredRoles.IsEmpty||!r.Commit.CommitSigned||!r.Commit.SourceMutationOccurred||r.Commit.ProductionEffectOccurred)throw new UnauthorizedAccessException("Invalid Git result authorization.");var d=access.Evaluate(new(r.Identity,r.Purpose,"git-commit-result.read",$"{r.OperationId:D}/{r.Commit.CommitId}",r.TenantId,r.MaximumClassification,r.RequiredRoles,ImmutableHashSet.Create(StringComparer.Ordinal,"developer.internal-service.git.commit"),r.SubjectId,false));var h=Convert.ToHexStringLower(SHA256.HashData(Encoding.UTF8.GetBytes($"{r.AuthorizationRequestId:D}|{r.Commit.CommitId}|{d.Code}")));return Task.FromResult(new GitResultAuthorizationDecision(r.AuthorizationRequestId,r.OperationId,r.TenantId,r.Commit.CommitId,d.IsAllowed,d.Code,r.EvidenceReferences.Append($"evidence://git/result-authorization/{r.AuthorizationRequestId:D}/sha256/{h}").ToImmutableArray(),r.RequestedAt));}
